function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < 1 || nums[i] > 10000) return 'Each value is an integer from 1 to 10^4.';
    if (i > 0 && nums[i - 1] > nums[i]) return 'nums must be sorted in non-decreasing order.';
  }
  return null;
}

