function getSumAbsoluteDifferences(nums) {
  const n = nums.length;
  let total = 0;
  for (const num of nums) {
    total += num;
  }
  const result = new Array(n);
  let leftSum = 0;
  for (let i = 0; i < n; i++) {
    const rightSum = total - leftSum - nums[i];
    const leftPart = nums[i] * i - leftSum;
    const rightPart = rightSum - nums[i] * (n - 1 - i);
    result[i] = leftPart + rightPart;
    leftSum += nums[i];
  }
  return result;
}

