function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 7);
  const high = size === 'large' ? 10000 : (rand() < 0.5 ? 5 : 30);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * high));
  nums.sort((a, b) => a - b);
  return [nums];
}
